window.AUTH=window.AUTH||{};window.AUTH["00-1021"]={"d":"00-1021","id":"2001/00-1021","n":"Rush Prudential HMO, Inc. v. Moran","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae","date":"","url":"https://www.justice.gov/osg/media/219911/dl?inline","side":"us","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/rush-prudential-v-moran-amicus-curiae-mertis","n":52}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep536/usrep536355/usrep536355.pdf","tr":false,"items":[{"t":"case","label":"Alessi v. Raybestos-Manhattan, Inc.","cite":"451 U.S. 504","y":1981,"id":"1980/79-1943","sc":1,"op":1,"sum":"In two suits initiated in New Jersey state court, retired employees who had received workers' compensation awards subsequent to retirement challenged the validity of provisions in their employers' pension plans reducing a retiree's pension benefits by an amount equal to a workers' compensation award for which the retiree is eligible. These private pension plans are subject to federal regulation under the Employee …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12"}},{"t":"case","label":"Barnett Bank v. Nelson","cite":"517 U.S. 25","y":1996,"id":"1995/94-1837","sc":1,"op":1,"sum":"Holding that a federal statute permitting banks to act as agents of insurance companies, although not insurers themselves, was a statute regulating the \"business of insurance\" for McCarran-Ferguson purposes.","sumSrc":"opinion","by":{"0":"16"}},{"t":"case","label":"Bowen v. United States Postal Service","cite":"459 U.S. 212","y":1983,"id":"1982/81-525","sc":1,"sum":"Where the District Court's findings, accepted by the Court of Appeals, established that petitioner's damages were caused initially by the USPS's unlawful discharge and were increased by the Union's breach of its duty of fair representation, apportionment of the damages was required. Vaca v. Sipes, 386 U. S. 171.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Chappel v. Laboratory Corp. of America","cite":"232 F.2d 721","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/232/721/","by":{"0":"24"}},{"t":"case","label":"Circuit City Stores, Inc. v. Adams","cite":"121 S. Ct. 1302","y":2001,"id":"2000/99-1379","sc":1,"op":4,"sum":"The Court held that section 1 exemption is confined to transportation workers. \"The wording of [section 1] calls for the application of the maxim ejusdem generis, the statutory canon that 'where general words follow specific words in a statutory enumeration, the general words are construed to embrace only objects similar in nature to those objects enumerated by the preceding specific words,'\" wrote Justice Kennedy.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Corporate Health Ins., Inc. v. Texas Dept. of Ins.","cite":"215 F.3d 526","y":2000,"url":"https://www.courtlistener.com/c/F.3d/215/526/","op":1,"by":{"0":"7, 8, 12"}},{"t":"case","label":"Department of Treasury v. Fabe","cite":"508 U.S. 491","y":1993,"id":"1992/91-1513","sc":1,"sum":"In proceedings under Ohio law to liquidate an insolvent insurance company, the United States asserted that its claims as obligee on various of the company's surety bonds were entitled to first priority under 31 U. S. C. §3713(a)(1)(A)(iii). Respondent Fabe, the liquidator appointed by the state court, brought a declaratory judgment action in the Federal District Court to establish that priority in such proceedings …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 17"}},{"t":"case","label":"Egelhoff v. Egelhoff","cite":"121 S. Ct. 1322","y":2001,"id":"2000/99-1529","sc":1,"op":4,"sum":"The Court held that that the Washington statute has a \"connection with\" ERISA plans and is therefore pre-empted. \"Differing state regulations affecting an ERISA plan's 'system for processing claims and paying benefits' impose 'precisely the burden that ERISA pre-emption was intended to avoid,'\" wrote Justice Thomas.","sumSrc":"Oyez","by":{"0":"6, 7"}},{"t":"case","label":"FMC Corp. v. Holliday","cite":"498 U.S. 52","y":1990,"id":"1990/89-1048","sc":1,"op":2,"sum":"Three provisions of ERISA speak to the question of preemption: the preemption clause, the saving clause, and the deemer clause. The preemption clause establishes as an area of exclusive federal concern the subject of every state law that \"relate[s] to\" an employee benefit plan governed by ERISA.","sumSrc":"Oyez","by":{"0":"6, 7, 11, 14, 20"}},{"t":"case","label":"Firestone Tire & Rubber Co. v. Bruch","cite":"489 U.S. 101","y":1989,"id":"1988/87-1054","sc":1,"op":4,"sum":"Petitioner Firestone Tire & Rubber Co. (Firestone) maintained, and was the plan administrator and fiduciary of, a termination pay plan and two other unfunded employee benefit plans governed by the Employee Retirement Income Security Act of 1974 (ERISA), 29 U. S. C. § 1001 et seq. After Firestone sold its Plastics Division to Occidental Petroleum Co. (Occidental), respondents, Plastics Division employees who were …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Franchise Tax Bd. v. Construction Laborers Vacation Trust","cite":"463 U.S. 1","y":1983,"id":"1982/82-695","sc":1,"sum":"The case is not within the removal jurisdiction conferred by 28 U. S. C. § 1441.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28, 29"}},{"t":"case","label":"Geier v. American Honda Motor Co., Inc.","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"sum":"The Court held that \"[Geier's] 'no airbag' lawsuit conflicts with the objectives of FMVSS 208 and is therefore pre-empted by the Act.\" Justice Breyer wrote for the Court that a rule of state tort law imposing a duty to install airbags in cars such as Honda's would have presented an obstacle to the variety and mix of devices that the federal regulation sought and to the phase-in that the federal regulation deliberately imposed.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"General Elec. Co. v. Gilbert","cite":"429 U.S. 125","y":1977,"id":"1975/74-1589","sc":1,"sum":"The Court held that employers have the right to exclude any condition from a disability plan with a reasonable basis.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"Group Life & Health Ins. Co. v. Royal Drug Co.","cite":"440 U.S. 205","y":1979,"id":"1978/77-952","sc":1,"op":3,"sum":"Explaining that the \"business of insurance\" is not coextensive with the \"business of insurers\".","sumSrc":"opinion","by":{"0":"13, 17"}},{"t":"case","label":"Harris Trust & Savings Bank v. Salomon Smith Barney","cite":"530 U.S. 238","y":2000,"id":"1999/99-579","sc":1,"op":4,"sum":"Recognizing that the agreement between an HMO and an employer may provide elements of a plan by setting out the rules under which care is provided.","sumSrc":"opinion","by":{"0":"23"}},{"t":"case","label":"Ingersoll-Rand Co. v. McClendon","cite":"498 U.S. 133","y":1990,"id":"1990/89-1298","sc":1,"op":7,"sum":"ERISA's explicit language and its structure and purpose demonstrate a congressional intent to pre-empt a state common law claim that an employee was unlawfully discharged to prevent his attainment of benefits under an ERISA-covered plan.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6, 19"}},{"t":"case","label":"Iron Workers Local 272 v. Bowen","cite":"624 F.2d 1255","y":1980,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/624/1255/","by":{"0":"22"}},{"t":"case","label":"John Hancock Mut. Life Ins. Co. v. Harris Trust & Sav. Bank","cite":"510 U.S. 86","y":1993,"id":"1993/92-1074","sc":1,"op":2,"sum":"Petitioner John Hancock Mutual Life Insurance Company (Hancock) and respondent Harris Trust and Savings Bank (Harris), the current trustee of a corporation's retirement plan, are party to Group Annuity Contract No. 50 (GAC 50), an agreement of a type known as a \"participating group annuity.\" Under such a contract, the insurer commingles with its general corporate assets deposits received to secure retiree benefits, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11"}},{"t":"case","label":"Mertens v. Hewitt Associates","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"sum":"ERISA does not authorize suits for money damages against nonfiduciaries who knowingly participate in a fiduciary's breach of fiduciary duty. ERISA §502(a)(3) permits plan participants to bring civil actions to obtain \"appropriate equitable relief\" to redress violations of the statute or a plan. Assuming, arguendo,that this creates a cause of action against nonfiduciaries who knowingly assist in a fiduciary's breach …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Metropolitan Life Ins. Co. v. Massachusetts","cite":"471 U.S. 724","y":1985,"id":"1984/84-325","sc":1,"op":10,"sum":"A Massachusetts statute (§ 47B) requires that certain minimum mentalhealth-care benefits be provided a Massachusetts resident who is insured under a general health insurance policy or an employee health-care plan that covers hospital and surgical expenses. Appellant insurer in No. 84-325 contends that § 47B, as applied to insurance policies purchased by employee health-care plans regulated by the federal Employee …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11, 14, 15, 17, 20, 25, 29"}},{"t":"case","label":"Metropolitan Life Ins. Co. v. Taylor","cite":"481 U.S. 58","y":1987,"id":"1986/85-686","sc":1,"op":12,"sum":"Section 502(a)(1)(B) of the Employee Retirement Income Security Act of 1974 (ERISA) provides that a participant or beneficiary may bring a civil action to, inter alia, recover benefits due him under the terms of an employee benefit plan. Under 28 U. S. C. § 1441(a), any civil action brought in state court of which the federal district courts have original jurisdiction may be removed by the defendant to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6, 7"}},{"t":"case","label":"Pappas v. Asbell","cite":"768 A.2d 1089","y":2001,"court":"Pa.","url":"https://www.courtlistener.com/c/A.2d/768/1089/","by":{"0":"7, 8, 12"}},{"t":"case","label":"Pilot Life Ins. Co. v. Dedeaux","cite":"481 U.S. 41","y":1987,"id":"1986/85-1043","sc":1,"op":22,"sum":"ERISA pre-empts respondent's suit under state common law for alleged improper processing of his claim for benefits under the ERISAregulated benefit plan.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Shaw v. Delta Air Lines, Inc.","cite":"463 U.S. 85","y":1983,"id":"1982/81-1578","sc":1,"sum":"New York's Human Rights Law forbids discrimination in employee benefit plans on the basis of pregnancy, and its Disability Benefits Law requires employers to pay sick-leave benefits to employees unable to work because of pregnancy. Section 514(a) of the federal Employee Retirement Income Security Act of 1974 (ERISA) provides, with enumerated exceptions, that ERISA shall supersede \"any and all state laws insofar as …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Textile Workers v. Lincoln Mills","cite":"353 U.S. 448","y":1957,"id":"1956/211","sc":1,"sum":"A union entered into a collective-bargaining agreement with an employer providing that there would be no strikes or work stoppages and that grievances would be handled pursuant to a specified procedure, the last step of which was arbitration. Grievances arose and were processed through various steps in the grievance procedure until the union's demands were finally denied by the employer. The union requested …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 24"}},{"t":"case","label":"UNUM Life Ins. Co. v. Ward","cite":"526 U.S. 358","y":1999,"id":"1998/97-1868","sc":1,"op":9,"sum":"Delivered by Justice Ruth Bader Ginsburg, the Court held that California's agency rule is preempted by the Employee Retirement Income Security Act of 1974. Justice Ginsburg wrote for the Court that California's common-law agency rule \"would have a marked effect on plan administration,\" adding that it would force employers to take on a role for which they had not volunteered.","sumSrc":"Oyez","by":{"0":"3, 11, 12, 16, 17, 20, 28, 29"}},{"t":"case","label":"Union Labor Life Ins. Co. v. Pireno","cite":"458 U.S. 119","y":1982,"id":"1981/81-389","sc":1,"op":2,"sum":"ULL's use of NYSCA's Peer Review Committee does not constitute the \"business of insurance\" within the meaning of § 2(b) of the McCarranFerguson Act, and thus is not exempt from antitrust scrutiny. Group Life & Health Ins. Co. v. Royal Drug Co., 440 U. S.205, controlling.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 17"}},{"t":"case","label":"United Paperworkers Int’l Union v. Misco, Inc.","cite":"484 U.S. 29","y":1988,"id":"1987/86-651","sc":1,"op":1,"sum":"Respondent employer's collective-bargaining agreement with petitioner union authorizes the submission to binding arbitration of any grievance that arises from the interpretation or application of the agreement's terms, and reserves to management the right to establish, amend, and enforce rules regulating employee discharge and discipline and setting forth disciplinary procedures. One of respondent's rules listed as …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 22, 26"}},{"t":"case","label":"United States Healthcare Sys. of Pa., Inc. v. Pennsylvania Hosp. Ins. Co.","cite":"530 U.S. 1241","y":2000,"url":"https://supreme.justia.com/cases/federal/us/530/1241/","sc":1,"op":4,"sum":"Recognizing that the agreement between an HMO and an employer may provide elements of a plan by setting out the rules under which care is provided.","sumSrc":"opinion","by":{"0":"10"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","stext":{"head":"§1001. Congressional findings and declaration of policy","paras":[[0,"(a) Benefit plans as affecting interstate commerce and the Federal taxing power"],[0,"The Congress finds that the growth in size, scope, and numbers of employee benefit plans in recent years has been rapid and substantial; that the operational scope and economic impact of such plans is increasingly interstate; that the continued well-being and security of millions of employees and their dependents are directly affected by these plans; that they are affected with a national public interest; that they have become an important factor affecting the stability of employment and the successful development of industrial relations; that they have become an important factor in commerce because of the interstate character of their activities, and of the activities of their participants, and the employers, employee organizations, and other entities by which they are established or maintained; that a large volume of the activities of such plans are carried on by means of the mails and instrumentalities of interstate commerce; that owing to the lack of employee information and adequate safeguards concerning their operation, it is desirable in the interests of employees and their beneficiaries, and to provide for the general welfare and the free flow of commerce, that disclosure be made and safeguards be provided with respect to the establishment, operation, and administration of such plans; that they substantially affect the revenues of the United States because they are afforded preferential Federal tax treatment; that despite the enormous growth in such plans many employees with long years of employment are losing anticipated retirement benefits owing to the lack of vesting provisions in such plans; that owing to the inadequacy of current minimum standards, the soundness and stability of plans with respect to adequate funds to pay promised benefits may be endangered; that owing to the termination of plans before requisite funds have been accumulated, employees and their beneficiaries have been deprived of anticipated benefits; and that it is therefore desirable in the interests of employees and their beneficiaries, for the protection of the revenue of the United States, and to provide for the free flow of commerce, that minimum standards be provided assuring the equitable character of such plans and their financial soundness."],[0,"(b) Protection of interstate commerce and beneficiaries by requiring disclosure and reporting, setting standards of conduct, etc., for fiduciaries"],[0,"It is hereby declared to be the policy of this chapter to protect interstate commerce and the interests of participants in employee benefit plans and their beneficiaries, by requiring the disclosure and reporting to participants and beneficiaries of financial and other information with respect thereto, by establishing standards of conduct, responsibility, and obligation for fiduciaries of employee benefit plans, and by providing for appropriate remedies, sanctions, and ready access to the Federal courts."],[0,"(c) Protection of interstate commerce, the Federal taxing power, and beneficiaries by vesting of accrued benefits, setting minimum standards of funding, requiring termination insurance"],[0,"It is hereby further declared to be the policy of this chapter to protect interstate commerce, the Federal taxing power, and the interests of participants in private pension plans and their beneficiaries by improving the equitable character and the soundness of such plans by requiring them to vest the accrued benefits of employees with significant periods of service, to meet minimum standards of funding, and by requiring plan termination insurance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1001?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1001. Congressional findings and declaration of policy","tname":"Labor","by":{"0":"10"}},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","subs":["(13)","(21)(A)(iii)"],"by":{"0":"10, 10"}},{"t":"usc","label":"29 U.S.C. § 1102","url":"https://www.law.cornell.edu/uscode/text/29/1102","subs":["(a)"],"by":{"0":"passim"}},{"t":"usc","label":"29 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/29/1104","subs":["(a)(1)(D)"],"by":{"0":"passim"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","subs":["(a)","(a)(1)(B)","(a)(2)"],"stext":{"head":"§1132. Civil enforcement","paras":[[0,"(a) Persons empowered to bring a civil action"],[0,"A civil action may be brought—"],[1,"(1) by a participant or beneficiary—"],[2,"(A) for the relief provided for in subsection (c) of this section, or"],[2,"(B) to recover benefits due to him under the terms of his plan, to enforce his rights under the terms of the plan, or to clarify his rights to future benefits under the terms of the plan;"],[1,"(2) by the Secretary, or by a participant, beneficiary or fiduciary for appropriate relief under section 1109 of this title;"],[1,"(3) by a participant, beneficiary, or fiduciary (A) to enjoin any act or practice which violates any provision of this subchapter or the terms of the plan, or (B) to obtain other appropriate equitable relief (i) to redress such violations or (ii) to enforce any provisions of this subchapter or the terms of the plan;"],[1,"(4) by the Secretary, or by a participant, or beneficiary for appropriate relief in the case of a violation of section 1025(c) or 1032(a) of this title;"],[1,"(5) except as otherwise provided in subsection (b), by the Secretary (A) to enjoin any act or practice which violates any provision of this subchapter, or (B) to obtain other appropriate equitable relief (i) to redress such violation or (ii) to enforce any provision of this subchapter;"],[1,"(6) by the Secretary to collect any civil penalty under paragraph (2), (4), (5), (6), (7), (8), or (9) of subsection (c) or under subsection (i) or (l);"],[1,"(7) by a State to enforce compliance with a qualified medical child support order (as defined in section 1169(a)(2)(A) of this title);"],[1,"(8) by the Secretary, or by an employer or other person referred to in section 1021(f)(1) of this title, (A) to enjoin any act or practice which violates subsection (f) of section 1021 of this title, or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection;"],[1,"(9) in the event that the purchase of an insurance contract or insurance annuity in connection with termination of an individual's status as a participant covered under a pension plan with respect to all or any portion of the participant's pension benefit under such plan constitutes a violation of part 4 of this title 1 or the terms of the plan, by the Secretary, by any individual who was a participant or beneficiary at the time of the alleged violation, or by a fiduciary, to obtain appropriate relief, including the posting of security if necessary, to assure receipt by the participant or beneficiary of the amounts provided or to be provided by such insurance contract or annuity, plus reasonable prejudgment interest on such amounts;"],[1,"(10) in the case of a multiemployer plan that has been certified by the actuary to be in endangered or critical status under section 1085 of this title, if the plan sponsor—"],[2,"(A) has not adopted a funding improvement or rehabilitation plan under that section by the deadline established in such section, or"],[2,"(B) fails to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section,"],[1,"by an employer that has an obligation to contribute with respect to the multiemployer plan or an employee organization that represents active participants in the multiemployer plan, for an order compelling the plan sponsor to adopt a funding improvement or rehabilitation plan or to update or comply with the terms of the funding improvement or rehabilitation plan in accordance with the requirements of such section and the funding improvement or rehabilitation plan; or"],[1,"(11) in the case of a multiemployer plan, by an employee representative, or any employer that has an obligation to contribute to the plan, (A) to enjoin any act or practice which violates subsection (k) of section 1021 of this title (or, in the case of an employer, subsection (l) of such section), or (B) to obtain appropriate equitable relief (i) to redress such violation or (ii) to enforce such subsection."],[0,"(b) Plans qualified under Internal Revenue Code; maintenance of actions involving delinquent contributions"],[0,"(1) In the case of a plan which is qualified under section 401(a), 403(a), or 405(a) 2 of title 26 (or with respect to which an application to so qualify has been filed and has not been finally determined) the Secretary may exercise his authority under subsection (a)(5) with respect to a violation of, or the enforcement of, parts 2 and 3 of this subtitle (relating to participation, vesting, and funding), only if—"],[1,"(A) requested by the Secretary of the Treasury, or"],[1,"(B) one or more participants, beneficiaries, or fiduciaries, of such plan request in writing (in such manner as the Secretary shall prescribe by regulation) that he exercise such authority on their behalf. In the case of such a request under this paragraph he may exercise such authority only if he determines that such violation affects, or such enforcement is necessary to protect, claims of participants or beneficiaries to benefits under the plan."],[0,"(2) The Secretary shall not initiate an action to enforce section 1145 of this title."],[0,"(3) Except as provided in subsections (c)(9) and (a)(6) (with respect to collecting civil penalties under subsection (c)(9)), the Secretary is not authorized to enforce under this part any requirement of part 7 against a health insurance issuer offering health insurance coverage in connection with a group health plan (as defined in section 1191b(a)(1) of this title). Nothing in this paragraph shall affect the authority of the Secretary to issue regulations to carry out such part."],[0,"(c) Administrator's refusal to supply requested information; penalty for failure to provide annual report in complete form"],[0,"(1) Any administrator (A) who fails to meet the requirements of paragraph (1) or (4) of section 1166 2 of this title, section 1021(e)(1) of this title, section 1021(f) of this title,,3 section 1025(a) of this title, or section 1032(a) of this title with respect to a participant or beneficiary, or (B) who fails or refuses to comply with a request for any information which such administrator is required by this subchapter to furnish to a participant or beneficiary (unless such failure or refusal results from matters reasonably beyond the control of the administrator) by mailing the material requested to the last known address of the requesting participant or beneficiary within 30 days after such request may in the court's discretion be personally liable to such participant or beneficiary in the amount of up to $100 a day from the date of such failure or refusal, and the court may in its discretion order such other relief as it deems proper. For purposes of this paragraph, each violation described in subparagraph (A) with respect to any single participant, and each violation described in subparagraph (B) with respect to any single participant or beneficiary, shall be treated as a separate violation."],[0,"(2) The Secretary may assess a civil penalty against any plan administrator of up to $1,000 a day from the date of such plan administrator's failure or refusal to file the annual report required to be filed with the Secretary under section 1021(b)(1) of this title. For purposes of this paragraph, an annual report that has been rejected under section 1024(a)(4) of this title for failure to provide material information shall not be treated as having been filed with the Secretary."],[0,"(3) Any employer maintaining a plan who fails to meet the notice requirement of section 1021(d) of this title with respect to any participant or beneficiary or who fails to meet the requirements of section 1021(e)(2) of this title with respect to any person or who fails to meet the requirements of section 1082(d)(12)(E) 2 of this title with respect to any person may in the court's discretion be liable to such participant or beneficiary or to such person in the amount of up to $100 a day from the date of such failure, and the court may in its discretion order such other relief as it deems proper."],[0,"(4) The Secretary may assess a civil penalty of not more than $1,000 a day for each violation by any person of subsection (j), (k), or (l) of section 1021 of this title or section 1144(e)(3) of this title."],[0,"(5) The Secretary may assess a civil penalty against any person of up to $1,000 a day from the date of the person's failure or refusal to file the information required to be filed by such person with the Secretary under regulations prescribed pursuant to section 1021(g) of this title."],[0,"(6) If, within 30 days of a request by the Secretary to a plan administrator for documents under section 1024(a)(6) of this title, the plan administrator fails to furnish the material requested to the Secretary, the Secretary may assess a civil penalty against the plan administrator of up to $100 a day from the date of such failure (but in no event in excess of $1,000 per request). No penalty shall be imposed under this paragraph for any failure resulting from matters reasonably beyond the control of the plan administrator."],[0,"(7) The Secretary may assess a civil penalty against a plan administrator of up to $100 a day from the date of the plan administrator's failure or refusal to provide notice to participants and beneficiaries in accordance with subsection (i) or (m) of section 1021 of this title. For purposes of this paragraph, each violation with respect to any single participant or beneficiary shall be treated as a separate violation."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1132?type=usc&year=mostrecent&link-type=html"},"op":11,"head":"§1132. Civil enforcement","tname":"Labor","by":{"0":"passim, passim, 9, 24, 25"}},{"t":"usc","label":"29 U.S.C. § 1133","url":"https://www.law.cornell.edu/uscode/text/29/1133","subs":["(2)"],"stext":{"head":"§1133. Claims procedure","paras":[[0,"In accordance with regulations of the Secretary, every employee benefit plan shall—"],[1,"(1) provide adequate notice in writing to any participant or beneficiary whose claim for benefits under the plan has been denied, setting forth the specific reasons for such denial, written in a manner calculated to be understood by the participant, and"],[1,"(2) afford a reasonable opportunity to any participant whose claim for benefits has been denied for a full and fair review by the appropriate named fiduciary of the decision denying the claim."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1133?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1133. Claims procedure","tname":"Labor","by":{"0":"9, 24, 25, 1, 4, 6, 10"}},{"t":"usc","label":"29 U.S.C. § 1136","url":"https://www.law.cornell.edu/uscode/text/29/1136","subs":["(b)"],"by":{"0":"1, 4, 6, 10"}},{"t":"usc","label":"29 U.S.C. § 1144","url":"https://www.law.cornell.edu/uscode/text/29/1144","subs":["(a)","(a)(2)(B)","(b)(2)(A)","(b)(2)(B)","(d)"],"stext":{"head":"§1144. Other laws","paras":[[0,"(a) Supersedure; effective date"],[0,"Except as provided in subsection (b) of this section, the provisions of this subchapter and subchapter III shall supersede any and all State laws insofar as they may now or hereafter relate to any employee benefit plan described in section 1003(a) of this title and not exempt under section 1003(b) of this title. This section shall take effect on January 1, 1975."],[0,"(b) Construction and application"],[0,"(1) This section shall not apply with respect to any cause of action which arose, or any act or omission which occurred, before January 1, 1975."],[0,"(2)(A) Except as provided in subparagraph (B), nothing in this subchapter shall be construed to exempt or relieve any person from any law of any State which regulates insurance, banking, or securities."],[0,"(B) Neither an employee benefit plan described in section 1003(a) of this title, which is not exempt under section 1003(b) of this title (other than a plan established primarily for the purpose of providing death benefits), nor any trust established under such a plan, shall be deemed to be an insurance company or other insurer, bank, trust company, or investment company or to be engaged in the business of insurance or banking for purposes of any law of any State purporting to regulate insurance companies, insurance contracts, banks, trust companies, or investment companies."],[0,"(3) Nothing in this section shall be construed to prohibit use by the Secretary of services or facilities of a State agency as permitted under section 1136 of this title."],[0,"(4) Subsection (a) shall not apply to any generally applicable criminal law of a State."],[0,"(5)(A) Except as provided in subparagraph (B), subsection (a) shall not apply to the Hawaii Prepaid Health Care Act (Haw. Rev. Stat. §§393–1 through 393–51)."],[0,"(B) Nothing in subparagraph (A) shall be construed to exempt from subsection (a)—"],[1,"(i) any State tax law relating to employee benefit plans, or"],[1,"(ii) any amendment of the Hawaii Prepaid Health Care Act enacted after September 2, 1974, to the extent it provides for more than the effective administration of such Act as in effect on such date."],[0,"(C) Notwithstanding subparagraph (A), parts 1 and 4 of this subtitle, and the preceding sections of this part to the extent they govern matters which are governed by the provisions of such parts 1 and 4, shall supersede the Hawaii Prepaid Health Care Act (as in effect on or after January 14, 1983), but the Secretary may enter into cooperative arrangements under this paragraph and section 1136 of this title with officials of the State of Hawaii to assist them in effectuating the policies of provisions of such Act which are superseded by such parts 1 and 4 and the preceding sections of this part."],[0,"(6)(A) Notwithstanding any other provision of this section—"],[1,"(i) in the case of an employee welfare benefit plan which is a multiple employer welfare arrangement and is fully insured (or which is a multiple employer welfare arrangement subject to an exemption under subparagraph (B)), any law of any State which regulates insurance may apply to such arrangement to the extent that such law provides—"],[2,"(I) standards, requiring the maintenance of specified levels of reserves and specified levels of contributions, which any such plan, or any trust established under such a plan, must meet in order to be considered under such law able to pay benefits in full when due, and"],[2,"(II) provisions to enforce such standards, and"],[1,"(ii) in the case of any other employee welfare benefit plan which is a multiple employer welfare arrangement, in addition to this subchapter, any law of any State which regulates insurance may apply to the extent not inconsistent with the preceding sections of this subchapter."],[0,"(B) The Secretary may, under regulations which may be prescribed by the Secretary, exempt from subparagraph (A)(ii), individually or by class, multiple employer welfare arrangements which are not fully insured. Any such exemption may be granted with respect to any arrangement or class of arrangements only if such arrangement or each arrangement which is a member of such class meets the requirements of section 1002(1) and section 1003 of this title necessary to be considered an employee welfare benefit plan to which this subchapter applies."],[0,"(C) Nothing in subparagraph (A) shall affect the manner or extent to which the provisions of this subchapter apply to an employee welfare benefit plan which is not a multiple employer welfare arrangement and which is a plan, fund, or program participating in, subscribing to, or otherwise using a multiple employer welfare arrangement to fund or administer benefits to such plan's participants and beneficiaries."],[0,"(D) For purposes of this paragraph, a multiple employer welfare arrangement shall be considered fully insured only if the terms of the arrangement provide for benefits the amount of all of which the Secretary determines are guaranteed under a contract, or policy of insurance, issued by an insurance company, insurance service, or insurance organization, qualified to conduct business in a State."],[0,"(7) Subsection (a) shall not apply to qualified domestic relations orders (within the meaning of section 1056(d)(3)(B)(i) of this title), qualified medical child support orders (within the meaning of section 1169(a)(2)(A) of this title), and the provisions of law referred to in section 1169(a)(2)(B)(ii) of this title to the extent they apply to qualified medical child support orders."],[0,"(8) Subsection (a) of this section shall not be construed to preclude any State cause of action—"],[1,"(A) with respect to which the State exercises its acquired rights under section 1169(b)(3) of this title with respect to a group health plan (as defined in section 1167(1) of this title), or"],[1,"(B) for recoupment of payment with respect to items or services pursuant to a State plan for medical assistance approved under title XIX of the Social Security Act [42 U.S.C. 1396 et seq.] which would not have been payable if such acquired rights had been executed before payment with respect to such items or services by the group health plan."],[0,"(9) For additional provisions relating to group health plans, see section 1191 of this title."],[0,"(c) Definitions"],[0,"For purposes of this section:"],[1,"(1) The term \"State law\" includes all laws, decisions, rules, regulations, or other State action having the effect of law, of any State. A law of the United States applicable only to the District of Columbia shall be treated as a State law rather than a law of the United States."],[1,"(2) The term \"State\" includes a State, any political subdivisions thereof, or any agency or instrumentality of either, which purports to regulate, directly or indirectly, the terms and conditions of employee benefit plans covered by this subchapter."],[0,"(d) Alteration, amendment, modification, invalidation, impairment, or supersedure of any law of the United States prohibited"],[0,"Nothing in this subchapter shall be construed to alter, amend, modify, invalidate, impair, or supersede any law of the United States (except as provided in sections 1031 and 1137(b) of this title) or any rule or regulation issued under any such law."],[0,"(e) Automatic contribution arrangements"],[0,"(1) Notwithstanding any other provision of this section, this subchapter shall supersede any law of a State which would directly or indirectly prohibit or restrict the inclusion in any plan of an automatic contribution arrangement. The Secretary may prescribe regulations which would establish minimum standards that such an arrangement would be required to satisfy in order for this subsection to apply in the case of such arrangement."],[0,"(2) For purposes of this subsection, the term \"automatic contribution arrangement\" means an arrangement—"],[1,"(A) under which a participant may elect to have the plan sponsor make payments as contributions under the plan on behalf of the participant, or to the participant directly in cash,"],[1,"(B) under which a participant is treated as having elected to have the plan sponsor make such contributions in an amount equal to a uniform percentage of compensation provided under the plan until the participant specifically elects not to have such contributions made (or specifically elects to have such contributions made at a different percentage), and"],[1,"(C) under which such contributions are invested in accordance with regulations prescribed by the Secretary under section 1104(c)(5) of this title."],[0,"(3)(A) The plan administrator of an automatic contribution arrangement shall, within a reasonable period before such plan year, provide to each participant to whom the arrangement applies for such plan year notice of the participant's rights and obligations under the arrangement which—"],[1,"(i) is sufficiently accurate and comprehensive to apprise the participant of such rights and obligations, and"],[1,"(ii) is written in a manner calculated to be understood by the average participant to whom the arrangement applies."],[0,"(B) A notice shall not be treated as meeting the requirements of subparagraph (A) with respect to a participant unless—"],[1,"(i) the notice includes an explanation of the participant's right under the arrangement not to have elective contributions made on the participant's behalf (or to elect to have such contributions made at a different percentage),"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1144?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§1144. Other laws","tname":"Labor","by":{"0":"1, 4, 6, 10, 14, 1, 3, 4, 11, 11, 20, 25"}},{"t":"usc","label":"9 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/9/1","stext":{"head":"§1. \"Maritime transactions\" and \"commerce\" defined; exceptions to operation of title","paras":[[0,"\"Maritime transactions\", as herein defined, means charter parties, bills of lading of water carriers, agreements relating to wharfage, supplies furnished vessels or repairs to vessels, collisions, or any other matters in foreign commerce which, if the subject of controversy, would be embraced within admiralty jurisdiction; \"commerce\", as herein defined, means commerce among the several States or with foreign nations, or in any Territory of the United States or in the District of Columbia, or between any such Territory and another, or between any such Territory and any State or foreign nation, or between the District of Columbia and any State or Territory or foreign nation, but nothing herein contained shall apply to contracts of employment of seamen, railroad employees, or any other class of workers engaged in foreign or interstate commerce."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/9/1?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1. \"Maritime transactions\" and \"commerce\" defined; exceptions to operation of title","tname":"Arbitration","by":{"0":"25"}},{"t":"usc","label":"42 U.S.C. § 300e","url":"https://www.law.cornell.edu/uscode/text/42/300e","subs":["(c)(2)"],"stext":{"head":"§300e. Requirements of health maintenance organizations","paras":[[0,"(a) \"Health maintenance organization\" defined"],[0,"For purposes of this subchapter, the term \"health maintenance organization\" means a public or private entity which is organized under the laws of any State and which (1) provides basic and supplemental health services to its members in the manner prescribed by subsection (b), and (2) is organized and operated in the manner prescribed by subsection (c)."],[0,"(b) Manner of supplying basic and supplemental health services to members"],[0,"A health maintenance organization shall provide, without limitations as to time or cost other than those prescribed by or under this subchapter, basic and supplemental health services to its members in the following manner:"],[1,"(1) Each member is to be provided basic health services for a basic health services payment which (A) is to be paid on a periodic basis without regard to the dates health services (within the basic health services) are provided; (B) is fixed without regard to the frequency, extent, or kind of health service (within the basic health services) actually furnished; (C) except in the case of basic health services provided a member who is a full-time student (as defined by the Secretary) at an accredited institution of higher education, is fixed under a community rating system; and (D) may be supplemented by additional nominal payments which may be required for the provision of specific services (within the basic health services), except that such payments may not be required where or in such a manner that they serve (as determined under regulations of the Secretary) as a barrier to the delivery of health services. Such additional nominal payments shall be fixed in accordance with the regulations of the Secretary. If a health maintenance organization offers to its members the opportunity to obtain basic health services through a physician not described in subsection (b)(3)(A), the organization may require, in addition to payments described in clause (D) of this paragraph, a reasonable deductible to be paid by a member when obtaining a basic health service from such a physician. A health maintenance organization may include a health service, defined as a supplemental health service by section 300e–1(2) of this title, in the basic health services provided its members for a basic health services payment described in the first sentence. In the case of an entity which before it became a qualified health maintenance organization (within the meaning of section 300e–9(d) 1 of this title) provided comprehensive health services on a prepaid basis, the requirement of clause (C) shall not apply to such entity until the expiration of the forty-eight month period beginning with the month following the month in which the entity became such a qualified health organization. The requirements of this paragraph respecting the basic health services payment shall not apply to the provision of basic health services to a member for an illness or injury for which the member is entitled to benefits under a workmen's compensation law or an insurance policy but only to the extent such benefits apply to such services. For the provision of such services for an illness or injury for which a member is entitled to benefits under such a law, the health maintenance organization may, if authorized by such law, charge or authorize the provider of such services to charge, in accordance with the charges allowed under such law, the insurance carrier, employer, or other entity which under such law is to pay for the provision of such services or, to the extent that such member has been paid under such law for such services, such member. For the provision of such services for an illness or injury for which a member is entitled to benefits under an insurance policy, a health maintenance organization may charge or authorize the provider of such services to charge the insurance carrier under such policy or, to the extent that such member has been paid under such policy for such services, such member."],[1,"(2) For such payment or payments (hereinafter in this subchapter referred to as \"supplemental health services payments\") as the health maintenance organization may require in addition to the basic health services payment, the organization may provide to each of its members any of the health services which are included in supplemental health services (as defined in section 300e–1(2) of this title). Supplemental health services payments which are fixed on a prepayment basis shall be fixed under a community rating system unless the supplemental health services payment is for a supplemental health service provided a member who is a full-time student (as defined by the Secretary) at an accredited institution of higher education, except that, in the case of an entity which before it became a qualified health maintenance organization (within the meaning of section 300e–9(d) 1 of this title) provided comprehensive health services on a prepaid basis, the requirement of this sentence shall not apply to such entity during the forty-eight month period beginning with the month following the month in which the entity became such a qualified health maintenance organization."],[1,"(3)(A) Except as provided in subparagraph (B), at least 90 percent of the services of a physician which are provided as basic health services shall be provided through—"],[2,"(i) members of the staff of the health maintenance organization,"],[2,"(ii) a medical group (or groups),"],[2,"(iii) an individual practice association (or associations),"],[2,"(iv) physicians or other health professionals who have contracted with the health maintenance organization for the provision of such services, or"],[2,"(v) any combination of such staff, medical group (or groups), individual practice association (or associations) or physicians or other health professionals under contract with the organization."],[1,"(B) Subparagraph (A) does not apply to the provision of the services of a physician—"],[2,"(i) which the health maintenance organization determines, in conformity with regulations of the Secretary, are unusual or infrequently used, or"],[2,"(ii) which are provided a member of the organization in a manner other than that prescribed by subparagraph (A) because of an emergency which made it medically necessary that the service be provided to the member before it could be provided in a manner prescribed by subparagraph (A)."],[1,"(C) Contracts between a health maintenance organization and health professionals for the provision of basic and supplemental health services shall include such provisions as the Secretary may require, but only to the extent that such requirements are designed to insure the delivery of quality health care services and sound fiscal management."],[1,"(D) For purposes of this paragraph the term \"health professional\" means physicians, dentists, nurses, podiatrists, optometrists, and such other individuals engaged in the delivery of health services as the Secretary may by regulation designate."],[1,"(4) Basic health services (and only such supplemental health services as members have contracted for) shall within the area served by the health maintenance organization be available and accessible to each of its members with reasonable promptness and in a manner which assures continuity, and when medically necessary be available and accessible twenty-four hours a day and seven days a week, except that a health maintenance organization which has a service area located wholly in a nonmetropolitan area may make a basic health service available outside its service area if that basic health service is not a primary care or emergency health care service and if there is an insufficient number of providers of that basic health service within the service area who will provide such service to members of the health maintenance organization. A member of a health maintenance organization shall be reimbursed by the organization for his expenses in securing basic and supplemental health services other than through the organization if the services were medically necessary and immediately required because of an unforeseen illness, injury, or condition."],[1,"(5) To the extent that a natural disaster, war, riot, civil insurrection, or any other similar event not within the control of a health maintenance organization (as determined under regulations of the Secretary) results in the facilities, personnel, or financial resources of a health maintenance organization not being available to provide or arrange for the provision of a basic or supplemental health service in accordance with the requirements of paragraphs (1) through (4) of this subsection, such requirements only require the organization to make a good-faith effort to provide or arrange for the provision of such service within such limitation on its facilities, personnel, or resources."],[1,"(6) A health maintenance organization that otherwise meets the requirements of this subchapter may offer a high-deductible health plan (as defined in section 220(c)(2) of title 26)."],[0,"(c) Organizational requirements"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/300e?type=usc&year=mostrecent&link-type=html"},"op":4,"sum":"Explaining that HMOs necessarily bear some of the risk of providing service, and requiring that a qualifying HMO \"assum[e] direct financial responsibility, without benefit of reinsurance, for care.., in excess of the first five thousand dollars per enrollee per year\".","sumSrc":"opinion","head":"§300e. Requirements of health maintenance organizations","tname":"The Public Health and Welfare","by":{"0":"12, 12"}},{"t":"usc","label":"42 U.S.C. § 300e-10","url":"https://www.law.cornell.edu/uscode/text/42/300e-10","subs":["(a)(1)(D)"],"stext":{"head":"§300e–10. Restrictive State laws and practices","paras":[[0,"(a) Entities operating as health maintenance organizations"],[0,"In the case of any entity—"],[1,"(1) which cannot do business as a health maintenance organization in a State in which it proposes to furnish basic and supplemental health services because that State by law, regulation, or otherwise—"],[2,"(A) requires as a condition to doing business in that State that a medical society approve the furnishing of services by the entity,"],[2,"(B) requires that physicians constitute all or a percentage of its governing body,"],[2,"(C) requires that all physicians or a percentage of physicians in the locale participate or be permitted to participate in the provision of services for the entity,"],[2,"(D) requires that the entity meet requirements for insurers of health care services doing business in that State respecting initial capitalization and establishment of financial reserves against insolvency, or"],[2,"(E) imposes requirements which would prohibit the entity from complying with the requirements of this subchapter, and"],[1,"(2) for which a grant, contract, loan, or loan guarantee was made under this subchapter or which is a qualified health maintenance organization for purposes of section 300e–9 of this title (relating to employees' health benefits plans),"],[0,"such requirements shall not apply to that entity so as to prevent it from operating as a health maintenance organization in accordance with section 300e of this title."],[0,"(b) Advertising"],[0,"No State may establish or enforce any law which prevents a health maintenance organization for which a grant, contract, loan, or loan guarantee was made under this subchapter or which is a qualified health maintenance organization for purposes of section 300e–9 of this title (relating to employees' health benefits plans), from soliciting members through advertising its services, charges, or other nonprofessional aspects of its operation. This subsection does not authorize any advertising which identifies, refers to, or makes any qualitative judgement concerning, any health professional who provides services for a health maintenance organization."],[0,"(c) Digest of State laws, regulations, and practices; legal consultative assistance"],[0,"The Secretary shall, within 6 months after October 8, 1976, develop a digest of State laws, regulations, and practices pertaining to development, establishment, and operation of health maintenance organizations which shall be updated at least annually and relevant sections of which shall be provided to the Governor of each State annually. Such digest shall indicate which State laws, regulations, and practices appear to be inconsistent with the operation of this section. The Secretary shall also insure that appropriate legal consultative assistance is available to the States for the purpose of complying with the provisions of this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/300e-10?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§300e–10. Restrictive State laws and practices","tname":"The Public Health and Welfare","by":{"0":"13"}},{"t":"usc","label":"29 U.S.C. § 185","url":"https://www.law.cornell.edu/uscode/text/29/185","by":{"0":"23, 24, 25, 26, 27, 28"}},{"t":"usc","label":"15 U.S.C. § 1012","url":"https://www.law.cornell.edu/uscode/text/15/1012","subs":["(b)"],"stext":{"head":"§1012. Regulation by State law; Federal law relating specifically to insurance; applicability of certain Federal laws after June 30, 1948","paras":[[0,"(a) State regulation"],[0,"The business of insurance, and every person engaged therein, shall be subject to the laws of the several States which relate to the regulation or taxation of such business."],[0,"(b) Federal regulation"],[0,"No Act of Congress shall be construed to invalidate, impair, or supersede any law enacted by any State for the purpose of regulating the business of insurance, or which imposes a fee or tax upon such business, unless such Act specifically relates to the business of insurance: Provided, That after June 30, 1948, the Act of July 2, 1890, as amended, known as the Sherman Act, and the Act of October 15, 1914, as amended, known as the Clayton Act, and the Act of September 26, 1914, known as the Federal Trade Commission Act, as amended [15 U.S.C. 41 et seq.], shall be applicable to the business of insurance to the extent that such business is not regulated by State Law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1012?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1012. Regulation by State law; Federal law relating specifically to insurance; applicability of certain Federal laws after June 30, 1948","tname":"Commerce and Trade","by":{"0":"17"}},{"t":"reg","label":"42 Fed. Reg. 27,426","url":"https://www.govinfo.gov/link/fr/42/27426","by":{"0":"10"}}]};